import math

def count_divisors(n):
    """Calculates the total number of positive divisors, tau(n)."""
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def d(n):
    """Calculates the number of positive divisors of n other than 1 and itself."""
    if n == 1:
        return 0
    tau_n = count_divisors(n)
    return tau_n - 2

# We are looking for d(n) = d(n + 735) = a, where a is the smallest possible value.
# We check n from 1 up to 300.
max_n = 300
results = []
min_a = float('inf')
found_solution = False

print("--- Searching for pairs (n, d(n)) where d(n) = d(n+735) ---")

for n in range(1, max_n + 1):
    d_n = d(n)
    n_plus_735 = n + 735
    d_n_plus_735 = d(n_plus_735)

    if d_n == d_n_plus_735:
        a = d_n
        results.append((n, a))
        if a < min_a:
            min_a = a
            found_solution = True
            print(f"Found a match for n={n} with a={a}. Current minimum a: {min_a}")

if not found_solution:
    print("No matches found in the range n=1 to 300.")
else:
    print("\n--- Summary of smallest observed 'a' ---")
    print(f"The smallest value of a found is: {min_a}")

print("\n--- Full list of matches found ---")
for n, a in results:
    print(f"n = {n}: d(n) = {a}, d(n+735) = {a}")

