def solve_case_p3(limit_p):
    solutions = []
    for p in range(2, limit_p):
        if p**2 > 10**6: # Stop if n gets too large for initial checks
             break

        # Check if p is prime (basic check for small p)
        is_p = True
        for i in range(2, int(p**0.5) + 1):
            if p % i == 0:
                is_p = False
                break
        if not is_p:
            continue

        n = p**3
        n_plus_735 = n + 735

        tau_n = count_divisors(n)
        tau_n_plus_735 = count_divisors(n_plus_735)

        if tau_n == 4 and tau_n_plus_735 == 4:
            solutions.append((n, n_plus_735))
            print(f"Found solution: n={n} ({p}^3). n+735={n_plus_735}.")

    return solutions

# Test up to p=30
solutions_p3 = solve_case_p3(30)
